{
  "title": "Discussion on tax workaround, domain purchase, app profitability, and password source",
  "topics": [
    {
      "id": "tax-workaround",
      "title": "Tax declaration workaround",
      "claims": [
        {
          "text": "Paying 500 UAH to aunt Sveta to fill missing columns in declarations can avoid larger penalties.",
          "evidence": [1]
        },
        {
          "text": "The inspector previously approved declarations without review and was later reprimanded, leading to a re‑audit of all years.",
          "evidence": [1]
        },
        {
          "text": "With Sveta's help the user repaid about 1000 UAH instead of paying all fines.",
          "evidence": [1]
        },
        {
          "text": "The main difficulty is correctly matching each column and subtraction, not the tax calculation itself.",
          "evidence": [8]
        },
        {
          "text": "Quarterly reports and correct tax payments are required.",
          "evidence": [7]
        }
      ]
    },
    {
      "id": "domain-purchase",
      "title": "Domain purchase discussion",
      "claims": [
        {
          "text": "User P2 has not bought a domain yet.",
          "evidence": [2]
        },
        {
          "text": "Someone needs to buy a calculator so there will be money for the domain.",
          "evidence": [4]
        },
        {
          "text": "P4 doubts the domain will be purchased.",
          "evidence": [9,10]
        }
      ]
    },
    {
      "id": "app-profitability",
      "title": "Profitability of a web/app project",
      "claims": [
        {
          "text": "Web platforms are the simplest but less profitable than Android/iOS.",
          "evidence": [11]
        },
        {
          "text": "Web SEO is poor; even on the 10th Google page the site is not found.",
          "evidence": [11]
        },
        {
          "text": "No external traffic sources (Instagram, Threads, contextual ads) are available for the web project.",
          "evidence": [11]
        },
        {
          "text": "User retention is near zero due to early paywall and email verification.",
          "evidence": [11]
        },
        {
          "text": "Fast delivery (< 1 week) and cross‑platform stack (Flutter) are recommended for success.",
          "evidence": [12]
        },
        {
          "text": "The project being discussed is Igor's attempt to earn money.",
          "evidence": [13,14]
        },
        {
          "text": "The calculator works only with UAH‑based FOP; the author had to convert transactions using daily exchange rates.",
          "evidence": [19]
        }
      ]
    },
    {
      "id": "password-source",
      "title": "Source code / password discussion",
      "claims": [
        {
          "text": "The app's source code is not publicly available; the password is stored locally as a 100 % discount promo code.",
          "evidence": [20]
        },
        {
          "text": "P4 denies having paid 299 UAH for the app.",
          "evidence": [22]
        },
        {
          "text": "P5 calls the app a pirate version.",
          "evidence": [24]
        },
        {
          "text": "P1 believes most LinkedIn users could hack the app without issues.",
          "evidence": [28]
        },
        {
          "text": "The app is positioned as a local‑first app with USD/UAH rate updating every 5 minutes, calculations done instantly in the browser.",
          "evidence": [29]
        },
        {
          "text": "P4 describes the project as a “free vibe‑code” with no real value; people might look for the password or ignore it.",
          "evidence": [30,31,32]
        },
        {
          "text": "P5 labels the project as a “vibe‑code” and confirms it is exactly that.",
          "evidence": [33,34]
        }
      ]
    }
  ],
